export function useTranslation() {
    const locale = usePage().props.locale === 'fr' ? 'fr' : 'en';
    const t = (key, replacements = {}) => {
        const value = key.split('.').reduce((current, part) => current?.[part], messages[locale]) ?? key;
        return Object.entries(replacements).reduce((text, [name, replacement]) => text.replaceAll(`:${name}`, String(replacement)), value);
    };
    return { locale, t };
}
